CREATE TABLE public.pacientes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), nome text NOT NULL, sexo text NOT NULL CHECK (sexo IN ('F','M')), nascimento date NOT NULL, altura_cm numeric, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,owner_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pacientes TO authenticated;
GRANT ALL ON public.pacientes TO service_role;
ALTER TABLE public.pacientes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_patients ON public.pacientes FOR ALL TO authenticated USING (owner_id=auth.uid()) WITH CHECK (owner_id=auth.uid());
CREATE TABLE public.avaliacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), paciente_id uuid NOT NULL, data date NOT NULL, peso_kg numeric NOT NULL CHECK(peso_kg>0), altura_cm numeric, protocolo text NOT NULL DEFAULT 'jp7' CHECK(protocolo IN ('jp7','jp3','dw')), medir_3x boolean NOT NULL DEFAULT false, circunferencias jsonb NOT NULL DEFAULT '{}', dobras jsonb NOT NULL DEFAULT '{}', bioimpedancia jsonb NOT NULL DEFAULT '{}', avaliador text, observacoes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (paciente_id,owner_id) REFERENCES public.pacientes(id,owner_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.avaliacoes TO authenticated;
GRANT ALL ON public.avaliacoes TO service_role;
ALTER TABLE public.avaliacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_assessments ON public.avaliacoes FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX assessment_patient_date ON public.avaliacoes(paciente_id,data);
CREATE INDEX patients_owner ON public.pacientes(owner_id);
CREATE INDEX assessments_owner ON public.avaliacoes(owner_id);
CREATE TABLE public.rascunhos (owner_id uuid PRIMARY KEY DEFAULT auth.uid(), avaliacao_id uuid, passo int NOT NULL DEFAULT 0 CHECK(passo BETWEEN 0 AND 6), dados jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rascunhos TO authenticated;
GRANT ALL ON public.rascunhos TO service_role;
ALTER TABLE public.rascunhos ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_drafts ON public.rascunhos FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE FUNCTION public.touch_assessment_updated() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER patients_updated BEFORE UPDATE ON public.pacientes FOR EACH ROW EXECUTE FUNCTION public.touch_assessment_updated();
CREATE TRIGGER assessments_updated BEFORE UPDATE ON public.avaliacoes FOR EACH ROW EXECUTE FUNCTION public.touch_assessment_updated();
CREATE TRIGGER drafts_updated BEFORE UPDATE ON public.rascunhos FOR EACH ROW EXECUTE FUNCTION public.touch_assessment_updated();
CREATE FUNCTION public.validate_assessment_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.data > (now() AT TIME ZONE 'America/Fortaleza')::date THEN RAISE EXCEPTION 'A avaliação não pode ter data futura'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER assessment_date BEFORE INSERT OR UPDATE ON public.avaliacoes FOR EACH ROW EXECUTE FUNCTION public.validate_assessment_date();